using System;
using System.IO;
using System.Collections.Generic;
using AirBridge.Routing;
public static class DefaultRouteTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void Run(string folder){Directory.CreateDirectory(folder);var state=new[]{"console-original","media-original"};var active=new HashSet<string>{"console-original","media-original","A","B","external"};bool fail=false;Action<string,int> write=(id,role)=>{if(fail&&role==1&&id=="B")throw new Exception("injected failure");state[role]=id;};Func<DefaultOutputRoute> create=()=>new DefaultOutputRoute(Path.Combine(folder,"defaults.xml"),role=>state[role],write,id=>active.Contains(id));var r=create();r.Apply("A");r.Apply("B");r.Restore();Check(state[0]=="console-original"&&state[1]=="media-original"&&r.PendingCount==0,"Original roles overwritten by reapply");r.Apply("A");fail=true;try{r.Apply("B");throw new Exception("expected failure");}catch(InvalidOperationException){}Check(state[0]=="A"&&state[1]=="A","Partial switch rollback failed");fail=false;create().Restore();Check(state[0]=="console-original"&&state[1]=="media-original","Crash journal recovery failed");r=create();r.Apply("A");state[0]="external";r.Restore();Check(state[0]=="external"&&state[1]=="media-original","External override clobbered");state[0]="console-original";r.Apply("A");active.Remove("media-original");try{r.Restore();throw new Exception("expected unavailable original");}catch(InvalidOperationException){}Check(r.PendingCount==1&&state[0]=="console-original","Missing-device recovery lost");active.Add("media-original");create().Restore();Check(state[1]=="media-original","Deferred restore failed");Console.WriteLine("PASS: default roles, reapply, rollback, crash recovery, external override, disconnected original");}
}
